namespace Bodu.Security.Cryptography
{
    public enum CubeHashVariants
    {
        CubeHash16_16_32_32_512,
        CubeHash160_16_32_160_512,
        CubeHash80_8_1_80_512,
        CubeHash10_1_1_10_512,
        CubeHash160_16_32_160_256,
        CubeHash80_8_1_80_256,
        CubeHash10_1_1_10_256
    }

    /// <summary>
    /// Contains unit tests for the <see cref="CubeHash" /> hash algorithm.
    /// </summary>
    [TestClass]
    public partial class CubeHashTests
        : Security.Cryptography.HashAlgorithmTests<CubeHashTests, CubeHash, CubeHashVariants>
    {
        private static readonly HashAlgorithmSpecification BaseCubeHashSpecification = new()
        {
            InputBlockSize = 1,
            HashSize = 256,
            OutputBlockSize = 1,
            LongInputLength = 200,
            MinNonZeroBytesForLongInput = null, // resolved from HashSize at runtime
            BoundaryLengths = [1, 8, 16, 64],
        };


        /// <inheritdoc />
        protected override CubeHash CreateAlgorithm() => new CubeHash();

        /// <inheritdoc />
        protected override HashAlgorithmSpecification GetSpecification(CubeHashVariants variant) => variant switch
        {
            CubeHashVariants.CubeHash16_16_32_32_512 => BaseCubeHashSpecification with { HashSize = 512, InputBlockSize = 32, OutputBlockSize = 32 },
            CubeHashVariants.CubeHash160_16_32_160_512 => BaseCubeHashSpecification with { HashSize = 512, InputBlockSize = 32, OutputBlockSize = 32 },
            CubeHashVariants.CubeHash80_8_1_80_512 => BaseCubeHashSpecification with { HashSize = 512, InputBlockSize = 1 },
            CubeHashVariants.CubeHash10_1_1_10_512 => BaseCubeHashSpecification with { HashSize = 512, InputBlockSize = 1 },
            CubeHashVariants.CubeHash160_16_32_160_256 => BaseCubeHashSpecification with { HashSize = 256, InputBlockSize = 32, OutputBlockSize = 32 },
            CubeHashVariants.CubeHash80_8_1_80_256 => BaseCubeHashSpecification with { HashSize = 256, InputBlockSize = 1 },
            CubeHashVariants.CubeHash10_1_1_10_256 => BaseCubeHashSpecification with { HashSize = 256, InputBlockSize = 1 },
            _ => throw new ArgumentOutOfRangeException(nameof(variant))
        };

        public override IEnumerable<CubeHashVariants> GetHashAlgorithmVariants() => new[]
        {
            CubeHashVariants.CubeHash16_16_32_32_512,
            CubeHashVariants.CubeHash160_16_32_160_512,
            CubeHashVariants.CubeHash80_8_1_80_512,
            CubeHashVariants.CubeHash10_1_1_10_512,
            CubeHashVariants.CubeHash160_16_32_160_256,
            CubeHashVariants.CubeHash80_8_1_80_256,
            CubeHashVariants.CubeHash10_1_1_10_256
        };

        protected override CubeHash CreateAlgorithm(CubeHashVariants variant) =>
            variant switch
            {
                CubeHashVariants.CubeHash16_16_32_32_512 => CreateAlgorithm(),
                CubeHashVariants.CubeHash160_16_32_160_512 => new CubeHash
                {
                    InitializationRounds = 160,
                    Rounds = 16,
                    TransformBlockSize = 32,
                    FinalizationRounds = 160,
                    HashSize = 512
                },
                CubeHashVariants.CubeHash80_8_1_80_512 => new CubeHash
                {
                    InitializationRounds = 80,
                    Rounds = 8,
                    TransformBlockSize = 1,
                    FinalizationRounds = 80,
                    HashSize = 512
                },
                CubeHashVariants.CubeHash10_1_1_10_512 => new CubeHash
                {
                    InitializationRounds = 10,
                    Rounds = 1,
                    TransformBlockSize = 1,
                    FinalizationRounds = 10,
                    HashSize = 512
                },
                CubeHashVariants.CubeHash160_16_32_160_256 => new CubeHash
                {
                    InitializationRounds = 160,
                    Rounds = 16,
                    TransformBlockSize = 32,
                    FinalizationRounds = 160,
                    HashSize = 256
                },
                CubeHashVariants.CubeHash80_8_1_80_256 => new CubeHash
                {
                    InitializationRounds = 80,
                    Rounds = 8,
                    TransformBlockSize = 1,
                    FinalizationRounds = 80,
                    HashSize = 256
                },
                CubeHashVariants.CubeHash10_1_1_10_256 => new CubeHash
                {
                    InitializationRounds = 10,
                    Rounds = 1,
                    TransformBlockSize = 1,
                    FinalizationRounds = 10,
                    HashSize = 256
                },
                _ => throw new ArgumentOutOfRangeException(nameof(variant))
            };

